// The shared house base: implements the panel_custom property contract
// (hass, narrow, route, panel) and a narrow-aware topbar. Its menu button
// appears only when `narrow` is true, matching built-in panels - without it
// there is no way back to the sidebar on a phone.
import { HaPanelBase, html, css } from "./vendor/ha-panel-base.js";

// zxing-wasm's DEFAULT locateFile is a hard-coded jsDelivr CDN URL, so vendoring
// the files is NOT enough: without this override the panel silently fetches the
// wasm from the internet and works everywhere except offline (#0310).
const BASE = new URL("./", import.meta.url).href;
let zx = null;
async function decoder() {
  if (zx) return zx;
  const m = await import("./vendor/reader/index.js");
  m.prepareZXingModule({
    overrides: {
      locateFile: (p, prefix) =>
        p.endsWith(".wasm") ? BASE + "vendor/reader/" + p : prefix + p,
    },
    fireImmediately: true,
  });
  zx = m;
  return m;
}

// ITF is deliberately absent: 6-digit interleaved 2-of-5 is a false-positive
// generator on busy packaging, and #0311 established these are all UPC-A anyway.
// UPC-A 036000291452, generated by zxing-wasm's own writer and verified to decode.
const SELFTEST = "iVBORw0KGgoAAAANSUhEUgAAAVMAAAA8CAAAAAD+9QaTAAAAnUlEQVR42u3QQQoAIQgFUO9/6ZldfNRgtgOvRYSZ2qvnvqrq7CeSwYrV8tvV+vx7cFbOQ7bLOjNhjpc/nXXWRm3UxY0pU6ZMmTJlypQpU6ZMmTJlypQpU6ZMmTJlypQpU6ZMmTJlypQpU6ZMmTJlypQpU6ZMmTJlypQpU6ZMmTJlypQpU6ZMmTJlypQpU6ZMmTJlypQpU6ZMmf7e9AXDJ7uTCI61TgAAAABJRU5ErkJggg==";
const FORMATS = ["UPC-A", "EAN-13", "EAN-8", "UPC-E"];
const STOCK_IN = "stock_in";
const USE_UP = "use_up";
const REVERT_SECONDS = 45;
// One physical package often carries TWO barcodes - a case code and the code on
// an individual item visible through or beside the carton. Both decode, four
// seconds apart, and the per-code guard cannot help because the payloads differ.
// Observed live: a gum case scanned +8, then a single pack +1, giving 15 where
// 14 was right. Suppress only when the SAME product is scanned again at a
// DIFFERENT unit count - that is the tell for one object read twice, whereas
// pack-then-pack at the same count is genuinely two items and stays fast.
const SAME_PRODUCT_WINDOW_MS = 8000;

// MIRRORS pantry_inventory/const.py DEPARTMENT_SLUGS and, through it,
// quick_shopping_list/const.py DEPARTMENTS. Hand-synced; the pantry test
// suite fails if the two Python copies drift.
const DEPARTMENTS = [
  ["produce", "Produce"],
  ["bakery", "Bakery"],
  ["bread_spreads", "Bread & Spreads"],
  ["deli", "Deli"],
  ["meat_seafood", "Meat & Seafood"],
  ["dairy_eggs", "Dairy & Eggs"],
  ["breakfast_cereal", "Breakfast & Cereal"],
  ["coffee_tea", "Coffee & Tea"],
  ["canned_dry", "Canned & Dry Goods"],
  ["condiments_sauces", "Condiments & Sauces"],
  ["baking_spices", "Baking & Spices"],
  ["snacks", "Snacks"],
  ["beverages", "Beverages"],
  ["alcohol", "Alcohol"],
  ["frozen", "Frozen"],
  ["household_paper", "Household & Paper"],
  ["health_beauty", "Health & Beauty"],
  ["pet", "Pet"],
  ["tools_hardware", "Tools & Hardware"],
  ["lumber_building", "Lumber & Building Materials"],
  ["paint_sundries", "Paint & Sundries"],
  ["electrical", "Electrical"],
  ["plumbing", "Plumbing"],
  ["garden_outdoor", "Garden & Outdoor"],
  ["automotive", "Automotive"],
  ["office_stationery", "Office & Stationery"],
  ["clothing", "Clothing"],
  ["other", "Other"],
];

class PantryInventoryPanel extends HaPanelBase {
  static properties = {
    _view: { state: true },
    _products: { state: true },
    _summary: { state: true },
    _stores: { state: true },
    _mode: { state: true },
    _scanning: { state: true },
    _tally: { state: true },
    _flash: { state: true },
    _revert: { state: true },
    _selfTest: { state: true },
    _muted: { state: true },
    _restock: { state: true },
    _fold: { state: true },
    _policy: { state: true },
  };

  constructor() {
    super();
    this._view = "scan";
    this._products = [];
    this._summary = {};
    this._stores = [];
    this._mode = USE_UP;          // the DAILY gesture is the default (#0316)
    this._scanning = false;
    this._tally = [];
    this._flash = null;
    this._revert = 0;
    this._selfTest = "running";
    this._muted = false;
    this._restock = null;
    this._fold = {};   // provisional_id -> target product_id, '' = create new
    this._policy = {}; // provisional_id -> "rate" | "par", chosen while naming
    this._recent = new Map();      // code -> last accepted ts
    this._accepted = new Map();    // product_id -> {units, ts}
    this._last = null;
    this._lastN = 0;
  }

  connectedCallback() {
    super.connectedCallback();
    this._resolveCameraFacing();
    this._load();
    this._runSelfTest();
    // The wall tablet navigates in with ?autostart=1 so the dashboard button is
    // one tap rather than two. A route change is not a user gesture, so this can
    // be refused - _startCamera reports that and leaves the normal tap-to-start
    // UI in place. Never assume it worked.
    if (this._autostart) this._startCamera();
  }

  // Which camera this DEVICE uses. #0312 chose `exact` so iOS could never hand
  // back the front camera silently; that stands. This is an explicit per-device
  // opt-in, not a fallback: nothing here ever downgrades a failed rear-camera
  // request to the front one. The wall tablet is flush-mounted, so its rear
  // camera faces drywall and `user` is the only workable choice there.
  // ?camera=user on the URL sets it once and persists, so the device
  // self-configures the first time the dashboard button is used.
  _resolveCameraFacing() {
    let facing = null;
    try {
      const q = new URLSearchParams(window.location.search);
      this._autostart = q.get("autostart") === "1";
      const want = q.get("camera");
      if (want === "user" || want === "environment") {
        facing = want;
        try { localStorage.setItem("pantry_camera_facing", want); } catch (e) { /* private mode */ }
      }
    } catch (e) { /* no URL access; fall through to storage */ }
    if (!facing) {
      try { facing = localStorage.getItem("pantry_camera_facing"); } catch (e) { /* blocked */ }
    }
    this._facing = facing === "user" ? "user" : "environment";
  }

  disconnectedCallback() {
    super.disconnectedCallback();
    this._stopCamera();
    clearInterval(this._revertTimer);
  }

  async _ws(type, payload = {}) {
    return this.hass.connection.sendMessagePromise({
      type: `pantry_inventory/${type}`,
      ...payload,
    });
  }

  async _load() {
    const d = await this._ws("dashboard");
    this._products = d.products || [];
    this._summary = d.summary || {};
    this._stores = d.store_options || [];
  }

  // A known-good barcode decoded at load. This is what separates "the decoder is
  // broken" from "the camera cannot see it" - without it, #0312 would still be
  // guessing. Cheap, and it earned its keep immediately.
  async _runSelfTest() {
    try {
      const m = await decoder();
      const png = Uint8Array.from(atob(SELFTEST), (c) => c.charCodeAt(0));
      const r = await m.readBarcodes(new Blob([png], { type: "image/png" }), {
        formats: FORMATS,
        tryHarder: true,
      });
      this._selfTest =
        r.length && r[0].text.endsWith("36000291452") ? "pass" : "fail";
    } catch (e) {
      this._selfTest = "error";
    }
  }

  // ---------- feedback ----------
  // navigator.vibrate does nothing on iOS in Safari OR a WKWebView (#0316).
  // HA's own haptic event is performed natively by the Companion app and
  // no-ops harmlessly in a browser.
  _feedback(kind, message) {
    this._flash = { kind, message };
    clearTimeout(this._flashTimer);
    this._flashTimer = setTimeout(() => (this._flash = null), 1400);
    this.dispatchEvent(
      new CustomEvent("haptic", {
        detail: kind === "good" ? "success" : "warning",
        bubbles: true,
        composed: true,
      })
    );
    this._beep(kind);
  }

  _beep(kind) {
    if (this._muted || !this._audio) return;
    try {
      const ctx = this._audio;
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      // two distinguishable tones: logged vs unknown-saved. At arm's length the
      // ear is the only channel that carries the difference.
      osc.frequency.value = kind === "good" ? 880 : 440;
      gain.gain.value = 0.09;
      osc.connect(gain).connect(ctx.destination);
      osc.start();
      osc.stop(ctx.currentTime + (kind === "good" ? 0.09 : 0.22));
    } catch (e) {
      /* audio is a nicety, never a failure */
    }
  }

  // ---------- camera ----------
  async _startCamera() {
    // iOS blocks audio until a user gesture, so the context is unlocked HERE,
    // on the tap, not on the first scan (#0316).
    try {
      this._audio = this._audio || new (window.AudioContext ||
        window.webkitAudioContext)();
      if (this._audio.state === "suspended") await this._audio.resume();
    } catch (e) { /* no audio; visual + haptic still work */ }

    try {
      // `exact` throws rather than silently handing back the FRONT camera, and
      // iOS never reports facingMode in getSettings() so you cannot check after
      // the fact (#0312).
      this._stream = await navigator.mediaDevices.getUserMedia({
        video: {
          facingMode: { exact: this._facing === "user" ? "user" : "environment" },
          width: { ideal: 1920 },
        },
        audio: false,
      });
    } catch (e) {
      // Name the camera that was refused. Without it a flush-mounted tablet
      // asking for the rear camera looks identical to a broken decoder.
      const hint = window.isSecureContext === false
        ? " - page is not a secure context, open HA over https"
        : "";
      this._feedback("bad", `${this._facing} camera refused: ${e.name}${hint}`);
      return;
    }
    this._scanning = true;
    await this.updateComplete;
    const v = this.renderRoot.querySelector("video");
    v.srcObject = this._stream;
    await v.play();
    this._loop();
  }

  _stopCamera() {
    cancelAnimationFrame(this._raf);
    if (this._stream) this._stream.getTracks().forEach((t) => t.stop());
    this._stream = null;
    this._scanning = false;
  }

  async _loop() {
    const v = this.renderRoot.querySelector("video");
    if (!v || !this._stream) return;
    if (v.videoWidth) {
      this._canvas = this._canvas || document.createElement("canvas");
      const c = this._canvas;
      c.width = v.videoWidth;
      c.height = v.videoHeight;
      const ctx = c.getContext("2d", { willReadFrequently: true });
      ctx.drawImage(v, 0, 0);
      try {
        const m = await decoder();
        const r = await m.readBarcodesFromImageData(
          ctx.getImageData(0, 0, c.width, c.height),
          { formats: FORMATS, tryHarder: true, maxNumberOfSymbols: 1 }
        );
        if (r.length) {
          const code = r[0].text;
          // Same payload on two consecutive frames - the single biggest
          // reliability lever, cheaper than tuning decoder options.
          if (code === this._last) {
            if (++this._lastN >= 2) {
              this._lastN = 0;
              const now = Date.now();
              if (!this._recent.has(code) || now - this._recent.get(code) > 2500) {
                const dupe = this._shouldSuppress(code);
                if (dupe) {
                  this._recent.set(code, now);
                  this._feedback(
                    "unknown",
                    `Ignored a second ${dupe.name} code (${dupe.units} vs ${this._accepted.get(dupe.product_id).units}) - scan again in a moment if you meant it`
                  );
                } else {
                  this._recent.set(code, now);
                  await this._submit(code);
                }
              }
            }
          } else {
            this._last = code;
            this._lastN = 1;
          }
        }
      } catch (e) { /* a bad frame is not an error */ }
    }
    this._raf = requestAnimationFrame(() => this._loop());
  }

  // The dashboard payload carries every product's barcodes, so a code can be
  // resolved to product + unit count WITHOUT asking the server - which matters,
  // because asking the server is what writes the event.
  _resolveLocally(code) {
    const padded = String(code).padStart(14, "0");
    for (const p of this._products) {
      const units = (p.barcodes || {})[padded];
      if (units !== undefined) return { product_id: p.product_id, units, name: p.name };
    }
    return null;
  }

  _shouldSuppress(code) {
    const hit = this._resolveLocally(code);
    if (!hit) return null;                    // unknown code: never suppress
    const prev = this._accepted.get(hit.product_id);
    if (!prev) return null;
    if (Date.now() - prev.ts > SAME_PRODUCT_WINDOW_MS) return null;
    if (prev.units === hit.units) return null; // same count = genuinely another item
    return hit;
  }

  async _submit(code) {
    try {
      const res = await this._ws("scan", { code, direction: this._mode });
      const s = res.state || {};
      const n = res.units || 1;
      const noun = s.unit_noun || "unit";
      if (res.provisional) {
        this._feedback("unknown", "Unknown code saved - name it later");
      } else {
        this._feedback(
          "good",
          `${this._mode === USE_UP ? "Used" : "Added"} ${n} ${noun}${n === 1 ? "" : "s"} - ${s.name}`
        );
      }
      this._accepted.set(res.product_id, { units: n, ts: Date.now() });
      this._tally = [
        { label: `${s.name || code} (${n} ${noun}${n === 1 ? "" : "s"})`,
          delta: this._mode === USE_UP ? -n : n,
          code,
          product_id: res.product_id },
        ...this._tally,
      ];
      if (this._mode === STOCK_IN) this._armRevert();
      await this._load();
    } catch (err) {
      // The websocket carries the refusal MESSAGE; the REST service would have
      // flattened it to an opaque 500 (#0312).
      this._feedback("bad", err.message || "Scan refused");
    }
  }

  // Leaving the panel in Stock In after a Costco run would ADD every bottle
  // consumed for the following week, silently, and the compliance figure would
  // measure nothing. The countdown is visible so the revert is never a surprise.
  _armRevert() {
    clearInterval(this._revertTimer);
    this._revert = REVERT_SECONDS;
    this._revertTimer = setInterval(() => {
      this._revert -= 1;
      if (this._revert <= 0) {
        clearInterval(this._revertTimer);
        this._mode = USE_UP;
      }
    }, 1000);
  }

  _setMode(mode) {
    this._mode = mode;
    if (mode === STOCK_IN) this._armRevert();
    else {
      clearInterval(this._revertTimer);
      this._revert = 0;
    }
  }

  async _undo(entry, index) {
    // Undo writes a compensating scan rather than deleting the event: the log is
    // append-only, and a mis-scan is part of the history worth keeping.
    try {
      await this._ws("scan", {
        code: entry.code,
        direction: entry.delta < 0 ? STOCK_IN : USE_UP,
      });
    } catch (e) { /* fall through to the count correction */ }
    this._tally = this._tally.filter((_, i) => i !== index);
    await this._load();
  }

  async _correct(p) {
    const answer = prompt(
      `How many ${p.unit_noun}s are actually there?`,
      Math.max(p.on_hand, 0)
    );
    if (answer === null || answer === "") return;
    try {
      await this._ws("set_count", {
        product_id: p.product_id,
        units: parseInt(answer, 10),
        event_type: "adjust",
      });
      this._feedback("good", "Count corrected");
      await this._load();
    } catch (err) {
      this._feedback("bad", err.message || "Refused");
    }
  }

  render() {
    return html`
      ${this._flash
        ? html`<div class="flash ${this._flash.kind}">${this._flash.message}</div>`
        : ""}
      <div class="wrap">
        ${this.renderTopbar(
          "Pantry",
          this._summary.products_below_threshold
            ? `${this._summary.products_below_threshold} below threshold`
            : "Scan in, scan out"
        )}
        ${this._view === "scan" ? this._renderScan() : ""}
        ${this._view === "stock" ? this._renderStock() : ""}
        ${this._view === "name" ? this._renderNaming() : ""}
      </div>
      <nav>
        ${["scan", "stock", "name"].map(
          (v) => html`
            <button
              class="${this._view === v ? "sel" : ""}"
              @click=${() => { this._view = v; if (v !== "scan") this._stopCamera(); }}
            >
              ${v === "scan" ? "Scan" : v === "stock" ? "Stock" : "Needs naming"}
              ${v === "name" && this._summary.products_needing_naming
                ? html`<span class="badge">${this._summary.products_needing_naming}</span>`
                : ""}
            </button>
          `
        )}
      </nav>
    `;
  }

  _renderScan() {
    return html`
      ${this._selfTest === "pass"
        ? ""
        : html`<div class="card selftest ${this._selfTest}">
            ${this._selfTest === "running"
              ? "Checking the decoder…"
              : "Decoder self-test FAILED - scanning will not work. The problem is the decoder, not the camera."}
          </div>`}
      <div class="mode">
        <button class="${this._mode === USE_UP ? "on-use" : "off"}"
          @click=${() => this._setMode(USE_UP)}>Use up</button>
        <button class="${this._mode === STOCK_IN ? "on-stock" : "off"}"
          @click=${() => this._setMode(STOCK_IN)}>Stock in</button>
      </div>
      ${this._revert > 0
        ? html`<div class="revert">Stock in - returns to Use up in ${this._revert}s</div>`
        : ""}
      <video playsinline muted ?hidden=${!this._scanning}></video>
      <div class="btns">
        ${this._scanning
          ? html`<button class="sec" @click=${this._stopCamera}>Stop</button>`
          : html`<button @click=${this._startCamera}>Start camera</button>`}
        <button class="sec" @click=${() => (this._muted = !this._muted)}>
          ${this._muted ? "Sound off" : "Sound on"}
        </button>
      </div>
      ${this._tally.length
        ? html`<div class="card">
            <h2>This session</h2>
            ${this._tally.map(
              (t, i) => html`<div class="tallyrow">
                <span>${t.label}</span>
                <span>
                  <span class="pill">${t.delta > 0 ? "+" : ""}${t.delta}</span>
                  <button class="sec sm" @click=${() => this._undo(t, i)}>Undo</button>
                </span>
              </div>`
            )}
          </div>`
        : ""}
    `;
  }

  _renderStock() {
    const sorted = [...this._products]
      .filter((p) => p.status === "active")
      .sort((a, b) => {
        // Below-threshold first, whichever policy decided it - otherwise a par
        // product with no days_of_supply sorts to the bottom precisely when it
        // needs buying.
        if (a.below_threshold !== b.below_threshold) return a.below_threshold ? -1 : 1;
        if (a.days_of_supply === null) return 1;
        if (b.days_of_supply === null) return -1;
        return a.days_of_supply - b.days_of_supply;
      });
    return html`${sorted.map((p) => this._card(p))}`;
  }

  // A par product has no rate and no days of supply, and showing an empty
  // "-d" beside it reads as a broken card rather than a deliberate choice. The
  // headline is the count against the par instead.
  _parCard(p) {
    const cls = p.on_hand <= 0 ? "low" : p.below_threshold ? "mid" : "ok";
    const noun = (n) => `${p.unit_noun}${n === 1 ? "" : "s"}`;
    return html`
      <div class="card">
        <div class="row">
          <span class="nm">${p.name}</span>
          <span class="days ${cls}">${Math.max(p.on_hand, 0)}/${p.threshold_units}</span>
        </div>
        <div class="meta">
          ${p.on_hand < 0
            ? html`<strong class="bad">0 &mdash; needs a count</strong>`
            : html`${p.on_hand} ${noun(p.on_hand)} on hand`}
          &middot; keep ${p.threshold_units} ${noun(p.threshold_units)} in
          ${p.purchase_quantity > 1
            ? html`&middot; buy ${p.purchase_quantity} at a time`
            : ""}
          <br />
          <span class="pill">by count</span>
          <span class="pill">${p.default_store || "All"}</span>
          ${p.department
            ? html`<span class="pill">${(DEPARTMENTS.find((d) => d[0] === p.department) || [, p.department])[1]}</span>`
            : ""}
          
          ${!p.push_armed ? html`<span class="pill warn">on the list</span>` : ""}
        </div>
        <div class="btns">
          <button class="sec sm" @click=${() => this._correct(p)}>Correct count</button>
          <button class="sec sm" @click=${() => (this._restock = p.product_id)}>
            Restock
          </button>
        </div>
        ${this._restock === p.product_id ? this._renderRestock(p) : ""}
      </div>
    `;
  }

  _card(p) {
    if (p.policy === "par") return this._parCard(p);
    const d = p.days_of_supply;
    const cls = d === null ? "" : d < 7 ? "low" : d < p.threshold_days ? "mid" : "ok";
    const rate =
      p.rate > 0
        ? p.rate >= 1
          ? `about ${p.rate.toFixed(1)} ${p.unit_noun}s a day`
          : `about one ${p.unit_noun} every ${Math.round(1 / p.rate)} days`
        : "no use in the last 21 days";
    return html`
      <div class="card">
        <div class="row">
          <span class="nm">${p.name}</span>
          <span class="days ${cls}">${d === null ? "—" : Math.round(d) + "d"}</span>
        </div>
        <div class="meta">
          ${p.on_hand < 0
            ? html`<strong class="bad">0 — needs a count</strong>`
            : html`${p.on_hand} ${p.unit_noun}${p.on_hand === 1 ? "" : "s"} on hand`}
          · ${rate}
          ${d === null
            ? html`<br /><span class="warn">
                ${p.unknown_reason === "no_consumption_in_window"
                  ? "No consumption in 21 days — not “plenty”, just unused"
                  : "Not enough scans yet to measure a rate"}
              </span>`
            : ""}
          <br />
          <span class="pill">${p.rate_source}${p.rate_source === "measured"
            ? ` (${p.rate_sample_size} scans)` : ""}</span>
          <span class="pill">${p.default_store || "All"}</span>
          ${p.department
            ? html`<span class="pill">${(DEPARTMENTS.find((d) => d[0] === p.department) || [, p.department])[1]}</span>`
            : ""}
          ${p.compliance_last_cycle !== null && p.compliance_last_cycle !== undefined
            ? html`<span class="pill ${p.compliance_last_cycle < 0.8 ? "warn" : ""}"
                >${Math.round(p.compliance_last_cycle * 100)}% scanned</span>`
            : html`<span class="pill">no cycle yet</span>`}
          ${!p.push_armed ? html`<span class="pill warn">on the list</span>` : ""}
        </div>
        <div class="btns">
          <button class="sec sm" @click=${() => this._correct(p)}>Correct count</button>
          <button class="sec sm" @click=${() => (this._restock = p.product_id)}>
            Restock
          </button>
        </div>
        ${this._restock === p.product_id ? this._renderRestock(p) : ""}
      </div>
    `;
  }

  // Two steps, deliberately. Step 1 is the ONLY moment compliance can be
  // measured; a "skip" would become the default under time pressure and the
  // pass criteria would be unevaluable (#0316).
  _renderRestock(p) {
    return html`
      <div class="stepnote">
        <strong>Step 1 of 2 — count what is left</strong><br />
        Before the new stock goes in. This is what measures whether scanning is
        keeping up. The log says <strong>${p.on_hand}</strong>.
      </div>
      <input type="number" inputmode="numeric" id="rc" .value=${Math.max(p.on_hand, 0)} />
      <div class="btns">
        <button @click=${() => this._reconcile(p)}>Next: scan the new packs</button>
        <button class="sec" @click=${() => (this._restock = null)}>Cancel</button>
      </div>
    `;
  }

  async _reconcile(p) {
    const input = this.renderRoot.querySelector("#rc");
    const actual = parseInt(input.value, 10);
    const drift = actual - p.on_hand;
    try {
      await this._ws("set_count", {
        product_id: p.product_id,
        units: actual,
        event_type: "reconcile",
      });
      this._restock = null;
      this._feedback(
        "good",
        drift === 0
          ? "Counted — nothing unscanned"
          : `Counted — ${Math.abs(drift)} ${p.unit_noun}${Math.abs(drift) === 1 ? "" : "s"} ${drift < 0 ? "unscanned" : "unaccounted"}`
      );
      await this._load();
      this._setMode(STOCK_IN);
      this._view = "scan";
    } catch (err) {
      this._feedback("bad", err.message || "Refused");
    }
  }

  _renderNaming() {
    const prov = this._products.filter((p) => p.status === "provisional");
    if (!prov.length) return html`<div class="card">Nothing to name.</div>`;
    const existing = this._products.filter((p) => p.status === "active");
    return html`${prov.map((p) => {
      const target = this._fold[p.product_id] || "";
      return html`
        <div class="card">
          <div class="meta">
            Scanned ${p.event_count}&times; &middot; ${Object.keys(p.barcodes).join(", ")}
          </div>

          <label>Is this something you already track?</label>
          <select @change=${(e) => {
            this._fold = { ...this._fold, [p.product_id]: e.target.value };
          }}>
            <option value="" ?selected=${!target}>Create a new product</option>
            ${existing.map(
              (x) => html`<option value=${x.product_id} ?selected=${target === x.product_id}>
                Add this barcode to ${x.name}
              </option>`
            )}
          </select>

          ${target
            ? html`
                <div class="stepnote">
                  A store selling a different pack size gives the same product a
                  different barcode. The
                  ${p.event_count === 1 ? "scan" : `${p.event_count} scans`}
                  already recorded here will be re-applied to that product at the
                  count you give below &mdash; nothing is lost.
                </div>
                <label>How many does THIS barcode represent?</label>
                <input id="c-${p.product_id}" type="number" inputmode="numeric" value="1" />
                <div class="btns">
                  <button @click=${() => this._fold_into(p, target)}>
                    Add to ${existing.find((x) => x.product_id === target)?.name}
                  </button>
                  <button class="sec" @click=${() => this._discard(p)}>Discard</button>
                </div>
              `
            : html`
                <label>Name</label>
                <input id="n-${p.product_id}" placeholder="e.g. Premier Protein" />
                <label>What is one of them called?</label>
                <input id="u-${p.product_id}" placeholder="bottle" />
                <label>How many does THIS barcode represent?</label>
                <input id="c-${p.product_id}" type="number" inputmode="numeric" value="1" />

                <label>Where is it in the shop?</label>
                <select id="d-${p.product_id}">
                  <option value="">Not sure yet</option>
                  ${DEPARTMENTS.map(
                    ([slug, label]) => html`<option value=${slug}>${label}</option>`
                  )}
                </select>

                <label>When should this go on the list?</label>
                <select
                  id="p-${p.product_id}"
                  @change=${(e) =>
                    (this._policy = { ...this._policy, [p.product_id]: e.target.value })}
                >
                  <option value="rate" selected>When it is about to run out</option>
                  <option value="par">When fewer than N are left</option>
                </select>

                ${(this._policy[p.product_id] || "rate") === "par"
                  ? html`
                      <div class="stepnote">
                        For things with no steady rate &mdash; jam, sauces,
                        spares. Nothing is projected: it goes on the list the
                        moment the count drops below the number you set.
                      </div>
                      <label>Always keep at least this many</label>
                      <input id="pu-${p.product_id}" type="number"
                             inputmode="numeric" value="2" min="1" />
                    `
                  : html`
                      <label>Roughly how many do you get through?</label>
                      <select id="r-${p.product_id}">
                        <option value="2">2 a day</option>
                        <option value="1">1 a day</option>
                        <option value="0.5">1 every 2 days</option>
                        <option value="0.25" selected>1 every 4 days</option>
                        <option value="0.143">1 a week</option>
                      </select>
                      <label>Warn me when this many days are left</label>
                      <input id="t-${p.product_id}" type="number"
                             inputmode="numeric" value="10" />
                    `}
                <label>How many do you buy at a time?</label>
                <input id="q-${p.product_id}" type="number"
                       inputmode="numeric" value="1" min="1" />

                <label>Which list?</label>
                <select id="s-${p.product_id}">
                  ${this._stores.map((x) => html`<option>${x}</option>`)}
                </select>
                <div class="btns">
                  <button @click=${() => this._saveNaming(p)}>Save</button>
                  <button class="sec" @click=${() => this._discard(p)}>Discard</button>
                </div>
              `}
        </div>
      `;
    })}`;
  }

  // Without this the queue fills with mis-scans and stops being opened at all -
  // which is how the whole naming flow dies (#0322).
  async _discard(p) {
    try {
      await this._ws("discard_provisional", { product_id: p.product_id });
      this._feedback("good", "Discarded");
      await this._load();
    } catch (err) {
      this._feedback("bad", err.message || "Refused");
    }
  }

  async _fold_into(p, target) {
    const units = parseInt(
      this.renderRoot.querySelector(`#c-${p.product_id}`).value, 10);
    if (!units || units < 1) return this._feedback("bad", "Needs a unit count");
    try {
      const res = await this._ws("attach_to_existing", {
        provisional_id: p.product_id, target_id: target, units,
      });
      this._feedback("good",
        `Added - ${res.scans_replayed} scan${res.scans_replayed === 1 ? "" : "s"} re-applied at ${units}`);
      this._fold = { ...this._fold, [p.product_id]: "" };
      await this._load();
    } catch (err) {
      this._feedback("bad", err.message || "Refused");
    }
  }

  async _saveNaming(p) {
    const g = (k) => this.renderRoot.querySelector(`#${k}-${p.product_id}`).value;
    if (!g("n")) return this._feedback("bad", "Needs a name");
    const policy = this._policy[p.product_id] || "rate";
    // Only the chosen policy's fields are rendered, so only they are sent. The
    // other threshold keeps whatever the record already holds - switching
    // policy and back must not silently reset it.
    const rule =
      policy === "par"
        ? { policy, threshold_units: parseInt(g("pu"), 10) }
        : {
            policy,
            initial_rate_estimate: parseFloat(g("r")),
            threshold_days: parseInt(g("t"), 10),
          };
    if (policy === "par" && !(rule.threshold_units >= 1))
      return this._feedback("bad", "Keep at least 1");
    // Independent of policy: how low to let it get and how many to buy are
    // different questions, and a rate product can be bought in pairs too.
    const purchase_quantity = parseInt(g("q"), 10);
    if (!(purchase_quantity >= 1)) return this._feedback("bad", "Buy at least 1");
    try {
      await this._ws("save_product", {
        product_id: p.product_id,
        name: g("n"),
        unit_noun: g("u") || "unit",
        default_store: g("s"),
        department: g("d"),
        purchase_quantity,
        ...rule,
      });
      for (const code of Object.keys(p.barcodes)) {
        await this._ws("attach_barcode", {
          code,
          product_id: p.product_id,
          units: parseInt(g("c"), 10),
        });
      }
      this._feedback("good", "Saved — earlier scans counted");
      await this._load();
    } catch (err) {
      this._feedback("bad", err.message || "Refused");
    }
  }

  static styles = [HaPanelBase.topbarStyles, css`
    :host { display: block; --red: #c62828; --amber: #f9a825; --green: #2e7d32;
            --line: var(--divider-color, rgba(128,128,128,.3));
            --dim: var(--secondary-text-color, rgba(128,128,128,.8));
            color: var(--primary-text-color); }
    .wrap { max-width: 620px; margin: 0 auto; padding: 14px 14px 88px; }
    .card { border: 1px solid var(--line); border-radius: 14px;
            padding: 13px 14px; margin-bottom: 11px; }
    .card h2 { font-size: 12px; text-transform: uppercase; letter-spacing: .06em;
               color: var(--dim); margin: 0 0 8px; }
    .row { display: flex; align-items: baseline; justify-content: space-between; gap: 10px; }
    .nm { font-weight: 600; }
    .days { font-size: 26px; font-weight: 700; line-height: 1; }
    .days.low { color: var(--red); } .days.mid { color: var(--amber); }
    .days.ok { color: var(--green); }
    .meta { color: var(--dim); font-size: 13px; margin-top: 5px; }
    .bad { color: var(--red); } .warn { color: var(--amber); }
    .pill { display: inline-block; font-size: 11px; padding: 2px 9px;
            border-radius: 999px; border: 1px solid var(--line); margin-right: 5px; }
    .pill.warn { color: var(--amber); border-color: var(--amber); }
    button { font: inherit; font-size: 15px; font-weight: 600; border-radius: 999px;
             border: 1px solid transparent; padding: 11px 18px;
             background: var(--green); color: #fff; cursor: pointer; }
    button.sec { background: transparent; color: inherit; border-color: var(--line); }
    button.sm { font-size: 13px; padding: 7px 14px; }
    .btns { display: flex; gap: 8px; margin-top: 11px; flex-wrap: wrap; }
    .mode { display: flex; gap: 8px; margin-bottom: 10px; }
    .mode button { flex: 1; padding: 16px 8px; font-size: 17px; }
    .mode .off { background: transparent; color: var(--dim); border-color: var(--line); }
    .mode .on-use { background: var(--green); color: #fff; }
    .mode .on-stock { background: var(--amber); color: #111; }
    .revert { color: var(--amber); font-size: 13px; margin-bottom: 8px; }
    video { width: 100%; border-radius: 14px; background: #000; display: block;
            aspect-ratio: 4/3; object-fit: cover; }
    video[hidden] { display: none; }
    .tallyrow { display: flex; justify-content: space-between; align-items: center;
                padding: 8px 0; border-bottom: 1px solid var(--line); font-size: 14px; }
    .flash { position: fixed; top: 0; left: 0; right: 0; padding: 15px;
             text-align: center; font-weight: 700; color: #fff; z-index: 9; }
    .flash.good { background: var(--green); }
    .flash.unknown { background: var(--amber); color: #111; }
    .flash.bad { background: var(--red); }
    .selftest.fail, .selftest.error { border-color: var(--red); color: var(--red); }
    nav { position: fixed; bottom: 0; left: 0; right: 0; display: flex;
          border-top: 1px solid var(--line);
          background: var(--card-background-color, Canvas); }
    nav button { flex: 1; border-radius: 0; background: transparent;
                 color: var(--dim); border: 0; padding: 13px 4px; font-size: 13px; }
    nav button.sel { color: var(--primary-text-color); box-shadow: inset 0 2px 0 var(--green); }
    .badge { display: inline-block; min-width: 19px; padding: 0 5px; border-radius: 999px;
             background: var(--amber); color: #111; font-size: 11px; font-weight: 700;
             margin-left: 4px; }
    label { display: block; font-size: 13px; color: var(--dim); margin: 10px 0 3px; }
    input, select { width: 100%; padding: 11px; border-radius: 12px;
                    border: 1px solid var(--line); background: transparent;
                    color: inherit; font: inherit; box-sizing: border-box; }
    .stepnote { border-left: 3px solid var(--amber); padding-left: 11px;
                margin: 12px 0; font-size: 14px; }
    /* The wall tablet is glanced at from across the kitchen: the headline number
       is the whole message, and six pills of provenance are noise (#0316). */
    @media (min-width: 700px) {
      .wrap { max-width: 900px; }
      .meta .pill { display: none; }
      .days { font-size: 34px; }
    }
  `];
}

customElements.define("pantry-inventory-panel", PantryInventoryPanel);
